package ken.example.dekiru.Mapper;

import ken.example.dekiru.DTO.Response.AdministrativeClassResponse;
import ken.example.dekiru.Entity.AdministrativeClass;
import org.mapstruct.AfterMapping;
import org.mapstruct.Mapper;
import org.mapstruct.MappingTarget;
import org.mapstruct.NullValueCheckStrategy;

import java.util.List;

@Mapper(componentModel = "spring", nullValueCheckStrategy = NullValueCheckStrategy.ALWAYS)
public interface AdministrativeClassMapper {

    AdministrativeClassResponse toAdministrativeClassResponse(AdministrativeClass administrativeClass);

    List<AdministrativeClassResponse> toAdministrativeClassResponseList(List<AdministrativeClass> administrativeClasses);

    AdministrativeClass toAdministrativeClass(AdministrativeClassResponse response);

    // After MapStruct mapping, fill in the teacher name từ nested object
    @AfterMapping
    default void fillHomeroomTeacherName(AdministrativeClass source, @MappingTarget AdministrativeClassResponse target) {
        if (source.getHomeroomTeacher() != null && 
            source.getHomeroomTeacher().getUser() != null) {
            target.setHomeroomTeacherFullName(source.getHomeroomTeacher().getUser().getFullName());
        }
    }
}

package ken.example.dekiru.Mapper;

