package ken.example.dekiru.Service;

import ken.example.dekiru.DTO.Request.UpdateAdministrativeClassRequest;
import ken.example.dekiru.DTO.Response.AdministrativeClassResponse;
import ken.example.dekiru.DTO.Response.ImportResponse;
import ken.example.dekiru.Entity.AdministrativeClass;
import ken.example.dekiru.Entity.Department;
import ken.example.dekiru.Entity.Lecturer;
import ken.example.dekiru.Mapper.AdministrativeClassMapper;
import ken.example.dekiru.Repository.AdministrativeClassRepository;
import ken.example.dekiru.Repository.DepartmentRepository;
import ken.example.dekiru.Repository.LecturerRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Workbook;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class AdministrativeClassService {

    AdministrativeClassRepository administrativeClassRepository;
    DepartmentRepository departmentRepository;
    LecturerRepository lecturerRepository;
    AdministrativeClassMapper administrativeClassMapper;

    // Lấy danh sách tất cả các lớp hành chính
    public List<AdministrativeClassResponse> getAllAdministrativeClasses() {
        List<AdministrativeClass> classes = administrativeClassRepository.findAll();
        return administrativeClassMapper.toAdministrativeClassResponseList(classes);
    }

    // Lấy thông tin lớp hành chính theo ID
    public AdministrativeClassResponse getAdministrativeClassById(Long id) {
        AdministrativeClass administrativeClass = administrativeClassRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.ADMINISTRATIVE_CLASS_NOT_EXISTED));
        return administrativeClassMapper.toAdministrativeClassResponse(administrativeClass);
    }

    @Transactional
    public ImportResponse importExcel(MultipartFile file) {
        if (file.isEmpty()) {
            throw new AppException(ErrorCode.FILE_IS_EMPTY);
        }

        int successCount = 0;
        int updateCount = 0;
        int errorCount = 0;
        List<String> errorDetails = new ArrayList<>();
        List<AdministrativeClass> classesToSave = new ArrayList<>();
        Set<String> codesInCurrentFile = new HashSet<>();
        int totalRows = 0; // ✅ Declare ở ngoài try-catch

        try (InputStream inputStream = file.getInputStream();
             Workbook workbook = new XSSFWorkbook(inputStream)) {

            Sheet sheet = workbook.getSheetAt(0);
            totalRows = sheet.getLastRowNum();

            // ✅ Validate headers
            Row headerRow = sheet.getRow(0);
            if (headerRow == null) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }
            List<String> expectedHeaders = List.of("Mã lớp", "Tên lớp", "Năm khoá", "Mã bộ môn", "Mã giáo viên");
            if (!validateHeaders(headerRow, expectedHeaders)) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }

            //  FIX N+1: Batch load tất cả codes từ Excel
            List<String> classCodesInFile = new ArrayList<>();
            List<String> depCodesInFile = new ArrayList<>();
            List<String> lecturerCodesInFile = new ArrayList<>();

            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;
                String classCode = getCellValue(row.getCell(0));
                String depCode = getCellValue(row.getCell(3));
                String lecCode = getCellValue(row.getCell(4));

                if (!classCode.isEmpty()) classCodesInFile.add(classCode);
                if (!depCode.isEmpty()) depCodesInFile.add(depCode);
                if (!lecCode.isEmpty()) lecturerCodesInFile.add(lecCode);
            }

            //  FIX N+1: 3 queries batch
            Map<String, AdministrativeClass> existingClassesMap = new HashMap<>();
            if (!classCodesInFile.isEmpty()) {
                List<AdministrativeClass> existing = administrativeClassRepository.findAllByCodeIn(classCodesInFile);
                for (AdministrativeClass cls : existing) {
                    existingClassesMap.put(cls.getCode(), cls);
                }
            }

            Map<String, Department> departmentsMap = new HashMap<>();
            if (!depCodesInFile.isEmpty()) {
                List<Department> deps = departmentRepository.findAllByCodeIn(depCodesInFile);
                for (Department dep : deps) {
                    departmentsMap.put(dep.getCode(), dep);
                }
            }

            Map<String, Lecturer> lecturersMap = new HashMap<>();
            if (!lecturerCodesInFile.isEmpty()) {
                List<Lecturer> lecturers = lecturerRepository.findAllByLecturerCodeIn(lecturerCodesInFile);
                for (Lecturer lec : lecturers) {
                    lecturersMap.put(lec.getLecturerCode(), lec);
                }
            }

            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;

                try {
                    String code = getCellValue(row.getCell(0));
                    String name = getCellValue(row.getCell(1));
                    String cohortYear = getCellValue(row.getCell(2));
                    String departmentCode = getCellValue(row.getCell(3));
                    String lecturerCode = getCellValue(row.getCell(4));

                    if (code.isEmpty() && name.isEmpty()) {
                        continue;
                    }

                    if (code.isEmpty() || name.isEmpty() || cohortYear.isEmpty() || departmentCode.isEmpty()) {
                        throw new RuntimeException("Mã lớp, Tên lớp, Năm khoá, Mã bộ môn không được để trống");
                    }

                    //  FIX DUPLICATE
                    if (codesInCurrentFile.contains(code)) {
                        throw new RuntimeException("Mã lớp '" + code + "' bị trùng trong file Excel");
                    }
                    codesInCurrentFile.add(code);

                    //  Từ Map, không query
                    Department department = departmentsMap.get(departmentCode);
                    if (department == null) {
                        throw new RuntimeException("Bộ môn với mã '" + departmentCode + "' không tồn tại");
                    }

                    Lecturer lecturer = null;
                    if (!lecturerCode.isEmpty()) {
                        lecturer = lecturersMap.get(lecturerCode);
                        if (lecturer == null) {
                            throw new RuntimeException("Giáo viên với mã '" + lecturerCode + "' không tồn tại");
                        }
                    }

                    AdministrativeClass existingClass = existingClassesMap.get(code);

                    if (existingClass != null) {
                        // Chỉ tính update nếu thực sự có thay đổi
                        boolean changed = !existingClass.getName().equals(name) ||
                                !existingClass.getCohortYear().equals(cohortYear) ||
                                !existingClass.getDepartment().getId().equals(department.getId()) ||
                                (lecturer == null ? existingClass.getHomeroomTeacher() != null : 
                                 !lecturer.getId().equals(existingClass.getHomeroomTeacher() != null ? existingClass.getHomeroomTeacher().getId() : null));

                        if (changed) {
                            existingClass.setName(name);
                            existingClass.setCohortYear(cohortYear);
                            existingClass.setDepartment(department);
                            existingClass.setHomeroomTeacher(lecturer);
                            classesToSave.add(existingClass);
                            updateCount++;
                        }
                    } else {
                        AdministrativeClass newClass = AdministrativeClass.builder()
                                .code(code)
                                .name(name)
                                .cohortYear(cohortYear)
                                .department(department)
                                .homeroomTeacher(lecturer)
                                .build();
                        classesToSave.add(newClass);
                        successCount++;
                    }
                } catch (Exception e) {
                    errorCount++;
                    errorDetails.add("Dòng " + (i + 1) + ": " + e.getMessage());
                }
            }

        } catch (Exception e) {
            throw new AppException(ErrorCode.FILE_PROCESSING_ERROR);
        }

        // PHASE 2: Lưu Database (ngoài try-catch)
        if (!classesToSave.isEmpty()) {
            administrativeClassRepository.saveAll(classesToSave);
        }

        return ImportResponse.builder()
                .totalRows(totalRows)
                .successCount(successCount)
                .updateCount(updateCount)
                .errorCount(errorCount)
                .errors(errorDetails)
                .build();
    }

    // ✅ Helper: Validate headers
    private boolean validateHeaders(Row headerRow, List<String> expectedHeaders) {
        for (int i = 0; i < expectedHeaders.size(); i++) {
            Cell cell = headerRow.getCell(i);
            String headerValue = getCellValue(cell).trim();
            if (!headerValue.equals(expectedHeaders.get(i))) {
                return false;
            }
        }
        return true;
    }

    private String getCellValue(Cell cell) {
        if (cell == null) return "";
        cell.setCellType(CellType.STRING);
        return cell.getStringCellValue().trim();
    }

    // ✅ Sửa lớp hành chính (chỉ sửa lecturerId - khóa ngoại)
    public AdministrativeClassResponse updateAdministrativeClass(Long id, UpdateAdministrativeClassRequest request) {
        AdministrativeClass administrativeClass = administrativeClassRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.ADMINISTRATIVE_CLASS_NOT_EXISTED));

        // Sửa giảng viên chủ nhiệm nếu có lecturerId
        if (request.getLecturerId() != null) {
            Lecturer lecturer = lecturerRepository.findById(request.getLecturerId())
                    .orElseThrow(() -> new AppException(ErrorCode.LECTURER_NOT_EXISTED));
            administrativeClass.setHomeroomTeacher(lecturer);
        }

        AdministrativeClass updated = administrativeClassRepository.save(administrativeClass);
        return administrativeClassMapper.toAdministrativeClassResponse(updated);
    }

    // ✅ Xóa lớp hành chính
    public void deleteAdministrativeClass(Long id) {
        AdministrativeClass administrativeClass = administrativeClassRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.ADMINISTRATIVE_CLASS_NOT_EXISTED));

        // Note: Khi ScheduleRepository được implement, thêm check:
        // long scheduleCount = scheduleRepository.countByAdministrativeClassId(id);
        // if (scheduleCount > 0) {
        //     throw new AppException(ErrorCode.ADMINISTRATIVE_CLASS_HAS_SCHEDULES);
        // }

        administrativeClassRepository.deleteById(id);
    }
}

package ken.example.dekiru.Service;

import ken.example.dekiru.DTO.Request.UpdateAdministrativeClassRequest;
import ken.example.dekiru.DTO.Response.AdministrativeClassResponse;
import ken.example.dekiru.DTO.Response.ImportResponse;
import ken.example.dekiru.Entity.AdministrativeClass;
import ken.example.dekiru.Entity.Department;
import ken.example.dekiru.Entity.Lecturer;
import ken.example.dekiru.Mapper.AdministrativeClassMapper;
import ken.example.dekiru.Repository.AdministrativeClassRepository;
import ken.example.dekiru.Repository.DepartmentRepository;
import ken.example.dekiru.Repository.LecturerRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Workbook;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class AdministrativeClassService {

    AdministrativeClassRepository administrativeClassRepository;
    DepartmentRepository departmentRepository;
    LecturerRepository lecturerRepository;
    AdministrativeClassMapper administrativeClassMapper;

    // Lấy danh sách tất cả các lớp hành chính
    public List<AdministrativeClassResponse> getAllAdministrativeClasses() {
        List<AdministrativeClass> classes = administrativeClassRepository.findAll();
        return administrativeClassMapper.toAdministrativeClassResponseList(classes);
    }

    // Lấy thông tin lớp hành chính theo ID
    public AdministrativeClassResponse getAdministrativeClassById(Long id) {
        AdministrativeClass administrativeClass = administrativeClassRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.ADMINISTRATIVE_CLASS_NOT_EXISTED));
        return administrativeClassMapper.toAdministrativeClassResponse(administrativeClass);
    }

    @Transactional
    public ImportResponse importExcel(MultipartFile file) {
        if (file.isEmpty()) {
            throw new AppException(ErrorCode.FILE_IS_EMPTY);
        }

        int successCount = 0;
        int updateCount = 0;
        int errorCount = 0;
        List<String> errorDetails = new ArrayList<>();
        List<AdministrativeClass> classesToSave = new ArrayList<>();
        Set<String> codesInCurrentFile = new HashSet<>();
        int totalRows = 0; // ✅ Declare ở ngoài try-catch

        try (InputStream inputStream = file.getInputStream();
             Workbook workbook = new XSSFWorkbook(inputStream)) {

            Sheet sheet = workbook.getSheetAt(0);
            totalRows = sheet.getLastRowNum();

            // ✅ Validate headers
            Row headerRow = sheet.getRow(0);
            if (headerRow == null) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }
            List<String> expectedHeaders = List.of("Mã lớp", "Tên lớp", "Năm khoá", "Mã bộ môn", "Mã giáo viên");
            if (!validateHeaders(headerRow, expectedHeaders)) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }

            //  FIX N+1: Batch load tất cả codes từ Excel
            List<String> classCodesInFile = new ArrayList<>();
            List<String> depCodesInFile = new ArrayList<>();
            List<String> lecturerCodesInFile = new ArrayList<>();

            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;
                String classCode = getCellValue(row.getCell(0));
                String depCode = getCellValue(row.getCell(3));
                String lecCode = getCellValue(row.getCell(4));

                if (!classCode.isEmpty()) classCodesInFile.add(classCode);
                if (!depCode.isEmpty()) depCodesInFile.add(depCode);
                if (!lecCode.isEmpty()) lecturerCodesInFile.add(lecCode);
            }

            //  FIX N+1: 3 queries batch
            Map<String, AdministrativeClass> existingClassesMap = new HashMap<>();
            if (!classCodesInFile.isEmpty()) {
                List<AdministrativeClass> existing = administrativeClassRepository.findAllByCodeIn(classCodesInFile);
                for (AdministrativeClass cls : existing) {
                    existingClassesMap.put(cls.getCode(), cls);
                }
            }

            Map<String, Department> departmentsMap = new HashMap<>();
            if (!depCodesInFile.isEmpty()) {
                List<Department> deps = departmentRepository.findAllByCodeIn(depCodesInFile);
                for (Department dep : deps) {
                    departmentsMap.put(dep.getCode(), dep);
                }
            }

            Map<String, Lecturer> lecturersMap = new HashMap<>();
            if (!lecturerCodesInFile.isEmpty()) {
                List<Lecturer> lecturers = lecturerRepository.findAllByLecturerCodeIn(lecturerCodesInFile);
                for (Lecturer lec : lecturers) {
                    lecturersMap.put(lec.getLecturerCode(), lec);
                }
            }

            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;

                try {
                    String code = getCellValue(row.getCell(0));
                    String name = getCellValue(row.getCell(1));
                    String cohortYear = getCellValue(row.getCell(2));
                    String departmentCode = getCellValue(row.getCell(3));
                    String lecturerCode = getCellValue(row.getCell(4));

                    if (code.isEmpty() && name.isEmpty()) {
                        continue;
                    }

                    if (code.isEmpty() || name.isEmpty() || cohortYear.isEmpty() || departmentCode.isEmpty()) {
                        throw new RuntimeException("Mã lớp, Tên lớp, Năm khoá, Mã bộ môn không được để trống");
                    }

                    //  FIX DUPLICATE
                    if (codesInCurrentFile.contains(code)) {
                        throw new RuntimeException("Mã lớp '" + code + "' bị trùng trong file Excel");
                    }
                    codesInCurrentFile.add(code);

                    //  Từ Map, không query
                    Department department = departmentsMap.get(departmentCode);
                    if (department == null) {
                        throw new RuntimeException("Bộ môn với mã '" + departmentCode + "' không tồn tại");
                    }

                    Lecturer lecturer = null;
                    if (!lecturerCode.isEmpty()) {
                        lecturer = lecturersMap.get(lecturerCode);
                        if (lecturer == null) {
                            throw new RuntimeException("Giáo viên với mã '" + lecturerCode + "' không tồn tại");
                        }
                    }

                    AdministrativeClass existingClass = existingClassesMap.get(code);

                    if (existingClass != null) {
                        // Chỉ tính update nếu thực sự có thay đổi
                        boolean changed = !existingClass.getName().equals(name) ||
                                !existingClass.getCohortYear().equals(cohortYear) ||
                                !existingClass.getDepartment().getId().equals(department.getId()) ||
                                (lecturer == null ? existingClass.getHomeroomTeacher() != null : 
                                 !lecturer.getId().equals(existingClass.getHomeroomTeacher() != null ? existingClass.getHomeroomTeacher().getId() : null));

                        if (changed) {
                            existingClass.setName(name);
                            existingClass.setCohortYear(cohortYear);
                            existingClass.setDepartment(department);
                            existingClass.setHomeroomTeacher(lecturer);
                            classesToSave.add(existingClass);
                            updateCount++;
                        }
                    } else {
                        AdministrativeClass newClass = AdministrativeClass.builder()
                                .code(code)
                                .name(name)
                                .cohortYear(cohortYear)
                                .department(department)
                                .homeroomTeacher(lecturer)
                                .build();
                        classesToSave.add(newClass);
                        successCount++;
                    }
                } catch (Exception e) {
                    errorCount++;
                    errorDetails.add("Dòng " + (i + 1) + ": " + e.getMessage());
                }
            }

        } catch (Exception e) {
            throw new AppException(ErrorCode.FILE_PROCESSING_ERROR);
        }

        // PHASE 2: Lưu Database (ngoài try-catch)
        if (!classesToSave.isEmpty()) {
            administrativeClassRepository.saveAll(classesToSave);
        }

        return ImportResponse.builder()
                .totalRows(totalRows)
                .successCount(successCount)
                .updateCount(updateCount)
                .errorCount(errorCount)
                .errors(errorDetails)
                .build();
    }

    // ✅ Helper: Validate headers
    private boolean validateHeaders(Row headerRow, List<String> expectedHeaders) {
        for (int i = 0; i < expectedHeaders.size(); i++) {
            Cell cell = headerRow.getCell(i);
            String headerValue = getCellValue(cell).trim();
            if (!headerValue.equals(expectedHeaders.get(i))) {
                return false;
            }
        }
        return true;
    }

    private String getCellValue(Cell cell) {
        if (cell == null) return "";
        cell.setCellType(CellType.STRING);
        return cell.getStringCellValue().trim();
    }

    // ✅ Sửa lớp hành chính (sửa name, cohortYear, lecturerId)
    public AdministrativeClassResponse updateAdministrativeClass(Long id, UpdateAdministrativeClassRequest request) {
        AdministrativeClass administrativeClass = administrativeClassRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.ADMINISTRATIVE_CLASS_NOT_EXISTED));

        if (request.getName() != null && !request.getName().trim().isEmpty()) {
            administrativeClass.setName(request.getName());
        }

        if (request.getCohortYear() != null && !request.getCohortYear().trim().isEmpty()) {
            administrativeClass.setCohortYear(request.getCohortYear());
        }

        // Sửa giảng viên chủ nhiệm nếu có lecturerId
        if (request.getLecturerId() != null) {
            Lecturer lecturer = lecturerRepository.findById(request.getLecturerId())
                    .orElseThrow(() -> new AppException(ErrorCode.LECTURER_NOT_EXISTED));
            administrativeClass.setHomeroomTeacher(lecturer);
        }

        AdministrativeClass updated = administrativeClassRepository.save(administrativeClass);
        return administrativeClassMapper.toAdministrativeClassResponse(updated);
    }

    // ✅ Xóa lớp hành chính
    public void deleteAdministrativeClass(Long id) {
        AdministrativeClass administrativeClass = administrativeClassRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.ADMINISTRATIVE_CLASS_NOT_EXISTED));

        // Note: Khi ScheduleRepository được implement, thêm check:
        // long scheduleCount = scheduleRepository.countByAdministrativeClassId(id);
        // if (scheduleCount > 0) {
        //     throw new AppException(ErrorCode.ADMINISTRATIVE_CLASS_HAS_SCHEDULES);
        // }

        administrativeClassRepository.deleteById(id);
    }
}

package ken.example.dekiru.attendance.repository;

import jakarta.persistence.LockModeType;
import ken.example.dekiru.attendance.dto.AttendanceSummaryDto;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.repository.query.Param;
import ken.example.dekiru.Entity.Attendance;
import ken.example.dekiru.Entity.CheckoutEvent;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public interface AttendanceRepository extends JpaRepository<Attendance, Long> {
    boolean existsByClassSession_Id(Long classSessionId);

    @Query("SELECT a FROM Attendance a JOIN FETCH a.student s JOIN FETCH s.user u WHERE a.classSession.id = :classSessionId")
    List<Attendance> findByClassSession_Id(@Param("classSessionId") Long classSessionId);

    @Query("""
    SELECT new ken.example.dekiru.attendance.dto.AttendanceSummaryDto(
        a.id, s.studentCode, u.fullName, a.status, a.scannedAt,
        a.isLate, a.lateMinutes, a.checkedOutAt, a.leftEarly, a.gpsVerified
    )
    FROM Attendance a
    JOIN a.student s
    JOIN s.user u
    WHERE a.classSession.id = :classSessionId
    """)
    List<AttendanceSummaryDto> findAttendanceSummaryBySessionId(@org.springframework.data.repository.query.Param("classSessionId") Long classSessionId);
    Optional<Attendance> findByClassSession_IdAndStudent_Id(Long classSessionId, Long studentId);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT a FROM Attendance a WHERE a.classSession.id = :classSessionId AND a.student.id = :studentId")
    Optional<Attendance> findByClassSessionIdAndStudentIdWithLock(
            @Param("classSessionId") Long classSessionId,
            @Param("studentId") Long studentId
    );
    boolean existsByClassSession_IdAndDeviceIdAndStatusAndStudent_IdNot(Long classSessionId, String deviceId, Attendance.Status status, Long studentId);

    @Modifying
    @Query("""
    UPDATE Attendance a
    SET a.leftEarly = true,
        a.checkoutEvent = :event
    WHERE a.classSession.id = :sessionId
      AND a.status = 'present'
      AND a.checkedOutAt IS NULL
    """)
    void markLeftEarlyForSession(
            @Param("sessionId") Long sessionId,
            @Param("event") CheckoutEvent event
    );
}

package ken.example.dekiru.attendance.repository;

import jakarta.persistence.LockModeType;
import ken.example.dekiru.attendance.dto.AttendanceSummaryDto;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.repository.query.Param;
import ken.example.dekiru.Entity.Attendance;
import ken.example.dekiru.Entity.CheckoutEvent;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public interface AttendanceRepository extends JpaRepository<Attendance, Long> {
    boolean existsByClassSession_Id(Long classSessionId);

    @Query("""
    SELECT a FROM Attendance a 
    JOIN FETCH a.student s 
    JOIN FETCH s.user u 
    LEFT JOIN FETCH a.editedBy 
    WHERE a.classSession.id = :classSessionId
    ORDER BY s.studentCode ASC
    """)
    List<Attendance> findByClassSession_Id(@Param("classSessionId") Long classSessionId);

    @Query("""
    SELECT new ken.example.dekiru.attendance.dto.AttendanceSummaryDto(
        a.id, s.studentCode, u.fullName, a.status, a.scannedAt,
        a.isLate, a.lateMinutes, a.checkedOutAt, a.leftEarly, a.gpsVerified
    )
    FROM Attendance a
    JOIN a.student s
    JOIN s.user u
    WHERE a.classSession.id = :classSessionId
    """)
    List<AttendanceSummaryDto> findAttendanceSummaryBySessionId(@org.springframework.data.repository.query.Param("classSessionId") Long classSessionId);
    Optional<Attendance> findByClassSession_IdAndStudent_Id(Long classSessionId, Long studentId);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT a FROM Attendance a WHERE a.classSession.id = :classSessionId AND a.student.id = :studentId")
    Optional<Attendance> findByClassSessionIdAndStudentIdWithLock(
            @Param("classSessionId") Long classSessionId,
            @Param("studentId") Long studentId
    );
    boolean existsByClassSession_IdAndDeviceIdAndStatusAndStudent_IdNot(Long classSessionId, String deviceId, Attendance.Status status, Long studentId);

    @Modifying
    @Query("""
    UPDATE Attendance a
    SET a.leftEarly = true,
        a.checkoutEvent = :event
    WHERE a.classSession.id = :sessionId
      AND a.status = 'present'
      AND a.checkedOutAt IS NULL
    """)
    void markLeftEarlyForSession(
            @Param("sessionId") Long sessionId,
            @Param("event") CheckoutEvent event
    );
}

package ken.example.dekiru.attendance.service;

import ken.example.dekiru.Entity.Attendance;
import ken.example.dekiru.attendance.dto.AttendanceSummaryDto;
import ken.example.dekiru.attendance.repository.AttendanceRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import ken.example.dekiru.Repository.ClassSessionRepository;
import ken.example.dekiru.Entity.ClassSession;
import ken.example.dekiru.common.Configuration.SecurityUtils;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

@Slf4j
@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE)
public class AttendanceSseService {

    @Value("${app.sse.timeout-ms:1800000}")
    Long sseTimeout;

    // sessionId -> danh sách emitter của các GV đang theo dõi buổi đó
    final Map<Long, CopyOnWriteArrayList<SseEmitter>> emitters = new ConcurrentHashMap<>();

    final AttendanceRepository attendanceRepository;
    final ClassSessionRepository classSessionRepository;
    final SecurityUtils securityUtils;

    /**
     * GV subscribe để nhận update real-time.
     * Ngay khi subscribe, server gửi luôn snapshot hiện tại.
     */
    public SseEmitter subscribe(Long sessionId) {
        Long lecturerId = securityUtils.getCurrentLecturerId();

        ClassSession session = classSessionRepository.findById(sessionId)
                .orElseThrow(() -> new AppException(ErrorCode.CLASS_SESSION_NOT_FOUND));

        if (!session.getActualLecturer().getId().equals(lecturerId)) {
            throw new AppException(ErrorCode.NO_PERMISSION_ON_SESSION);
        }

        // Sử dụng timeout từ config (mặc định 30p nếu ko có config)
        SseEmitter emitter = new SseEmitter(sseTimeout);

        // Đăng ký emitter vào map
        emitters.computeIfAbsent(sessionId, k -> new CopyOnWriteArrayList<>()).add(emitter);

        // Dọn emitter khi kết nối kết thúc / lỗi
        Runnable cleanup = () -> removeEmitter(sessionId, emitter);
        emitter.onCompletion(cleanup);
        emitter.onTimeout(cleanup);
        emitter.onError(e -> {
            log.warn("SSE error sessionId={}: {}", sessionId, e.getMessage());
            cleanup.run();
        });

        // Gửi ngay snapshot hiện tại để client không phải chờ event đầu tiên
        try {
            List<AttendanceSummaryDto> snapshot = buildSnapshot(sessionId);
            emitter.send(SseEmitter.event()
                    .name("snapshot")
                    .data(snapshot));
        } catch (IOException | IllegalStateException e) {
            log.warn("Failed to send initial snapshot to sessionId={}", sessionId);
            // Gửi lỗi về client nếu có thể trước khi hoàn thành
            try {
                emitter.send(SseEmitter.event().name("error").data("Lỗi khởi tạo dữ liệu"));
            } catch (Exception ignored) {}
            emitter.completeWithError(e);
        }

        return emitter;
    }

    /**
     * Gửi heartbeat định kỳ để giữ kết nối không bị timeout bởi Proxy/Load Balancer (Nginx)
     * và dọn dẹp các emitter đã hỏng.
     */
    @Scheduled(fixedDelayString = "${app.sse.heartbeat-interval-ms:25000}")
    public void sendHeartbeat() {
        if (emitters.isEmpty()) return;

        log.debug("Sending SSE heartbeats for {} sessions", emitters.size());
        emitters.forEach((sessionId, list) -> {
            for (SseEmitter emitter : list) {
                try {
                    emitter.send(SseEmitter.event()
                            .name("ping")
                            .comment("keep-alive"));
                } catch (IOException | IllegalStateException e) {
                    log.debug("Removing broken emitter for session {}: {}", sessionId, e.getMessage());
                    removeEmitter(sessionId, emitter);
                }
            }
        });
    }

    /**
     * Gọi sau mỗi lần SV quét QR thành công (từ ClassSessionService).
     * Đẩy bản ghi điểm danh đã cập nhật tới tất cả GV đang subscribe.
     */
    public void pushAttendanceUpdate(Long sessionId, Attendance attendance) {
        CopyOnWriteArrayList<SseEmitter> sessionEmitters = emitters.get(sessionId);
        if (sessionEmitters == null || sessionEmitters.isEmpty()) return;

        AttendanceSummaryDto dto = toDto(attendance);

        for (SseEmitter emitter : sessionEmitters) {
            try {
                emitter.send(SseEmitter.event()
                        .name("attendance-update")  // client lắng nghe event tên này
                        .data(dto));
            } catch (IOException | IllegalStateException e) {
                log.warn("Failed to push update to emitter, removing. sessionId={}", sessionId);
                removeEmitter(sessionId, emitter);
            }
        }
    }

    /**
     * Gọi khi GV đóng buổi học — báo client kết thúc stream.
     */
    public void pushSessionClosed(Long sessionId) {
        CopyOnWriteArrayList<SseEmitter> sessionEmitters = emitters.get(sessionId);
        if (sessionEmitters == null) return;

        for (SseEmitter emitter : sessionEmitters) {
            try {
                emitter.send(SseEmitter.event()
                        .name("session-closed")
                        .data("Buổi học đã kết thúc"));
                emitter.complete();
            } catch (IOException | IllegalStateException e) {
                log.warn("Failed to send session-closed event. sessionId={}", sessionId);
                removeEmitter(sessionId, emitter);
            }
        }
        emitters.remove(sessionId);
    }

    // ----------------------------------------------------------------
    // Helper
    // ----------------------------------------------------------------

    private List<AttendanceSummaryDto> buildSnapshot(Long sessionId) {
        return attendanceRepository.findAttendanceSummaryBySessionId(sessionId);
    }

    private AttendanceSummaryDto toDto(Attendance a) {
        return new AttendanceSummaryDto(
                a.getId(),
                a.getStudent().getStudentCode(),
                a.getStudent().getUser().getFullName(),
                a.getStatus(),
                a.getScannedAt(),
                a.getIsLate(),
                a.getLateMinutes() != null ? (short) a.getLateMinutes() : null,
                a.getCheckedOutAt(),
                a.getLeftEarly(),
                a.getGpsVerified()
        );
    }

    private void removeEmitter(Long sessionId, SseEmitter emitter) {
        CopyOnWriteArrayList<SseEmitter> list = emitters.get(sessionId);
        if (list != null) {
            list.remove(emitter);
            if (list.isEmpty()) emitters.remove(sessionId);
        }
    }

    /**
     * Gọi từ CheckoutEventScheduler sau khi markLeftEarlyForSession().
     * Nhiều SV bị cập nhật cùng lúc nên gửi lại toàn bộ snapshot thay vì từng record.
     */
    public void pushLeftEarlyUpdate(Long sessionId) {
        CopyOnWriteArrayList<SseEmitter> sessionEmitters = emitters.get(sessionId);
        if (sessionEmitters == null || sessionEmitters.isEmpty()) return;

        List<AttendanceSummaryDto> snapshot = buildSnapshot(sessionId);

        for (SseEmitter emitter : sessionEmitters) {
            try {
                emitter.send(SseEmitter.event()
                        .name("left-early-update")   // client phân biệt với "attendance-update"
                        .data(snapshot));
            } catch (IOException | IllegalStateException e) {
                log.warn("Failed to push left-early-update. sessionId={}", sessionId);
                removeEmitter(sessionId, emitter);
            }
        }
    }
}

package ken.example.dekiru.attendance.service;

import ken.example.dekiru.Entity.Attendance;
import ken.example.dekiru.attendance.dto.AttendanceSummaryDto;
import ken.example.dekiru.attendance.repository.AttendanceRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import ken.example.dekiru.Repository.ClassSessionRepository;
import ken.example.dekiru.Entity.ClassSession;
import ken.example.dekiru.common.Configuration.SecurityUtils;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

@Slf4j
@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE)
public class AttendanceSseService {

    @Value("${app.sse.timeout-ms:1800000}")
    Long sseTimeout;

    // sessionId -> danh sách emitter của các GV đang theo dõi buổi đó
    final Map<Long, CopyOnWriteArrayList<SseEmitter>> emitters = new ConcurrentHashMap<>();

    final AttendanceRepository attendanceRepository;
    final ClassSessionRepository classSessionRepository;
    final SecurityUtils securityUtils;

    /**
     * GV subscribe để nhận update real-time.
     * Ngay khi subscribe, server gửi luôn snapshot hiện tại.
     */
    public SseEmitter subscribe(Long sessionId) {
        Long lecturerId = securityUtils.getCurrentLecturerId();

        ClassSession session = classSessionRepository.findById(sessionId)
                .orElseThrow(() -> new AppException(ErrorCode.CLASS_SESSION_NOT_FOUND));

        if (!session.getActualLecturer().getId().equals(lecturerId)) {
            throw new AppException(ErrorCode.NO_PERMISSION_ON_SESSION);
        }

        // Sử dụng timeout từ config (mặc định 30p nếu ko có config)
        SseEmitter emitter = new SseEmitter(sseTimeout);

        // Đăng ký emitter vào map
        emitters.computeIfAbsent(sessionId, k -> new CopyOnWriteArrayList<>()).add(emitter);

        // Dọn emitter khi kết nối kết thúc / lỗi
        Runnable cleanup = () -> removeEmitter(sessionId, emitter);
        emitter.onCompletion(cleanup);
        emitter.onTimeout(cleanup);
        emitter.onError(e -> {
            String msg = e.getMessage();
            // Nếu là lỗi ngắt kết nối bình thường từ phía Client, chỉ log DEBUG thay vì WARN
            if (msg != null && (msg.contains("disconnected client") || msg.contains("Broken pipe") || msg.contains("Connection reset"))) {
                log.debug("SSE disconnected client sessionId={}", sessionId);
            } else {
                log.warn("SSE error sessionId={}: {}", sessionId, e.getMessage());
            }
            cleanup.run();
        });

        // Gửi ngay snapshot hiện tại để client không phải chờ event đầu tiên
        try {
            List<AttendanceSummaryDto> snapshot = buildSnapshot(sessionId);
            emitter.send(SseEmitter.event()
                    .name("snapshot")
                    .data(snapshot));
        } catch (IOException | IllegalStateException e) {
            log.warn("Failed to send initial snapshot to sessionId={}", sessionId);
            // Gửi lỗi về client nếu có thể trước khi hoàn thành
            try {
                emitter.send(SseEmitter.event().name("error").data("Lỗi khởi tạo dữ liệu"));
            } catch (Exception ignored) {}
            emitter.completeWithError(e);
        }

        return emitter;
    }

    /**
     * Gửi heartbeat định kỳ để giữ kết nối không bị timeout bởi Proxy/Load Balancer (Nginx)
     * và dọn dẹp các emitter đã hỏng.
     */
    @Scheduled(fixedDelayString = "${app.sse.heartbeat-interval-ms:25000}")
    public void sendHeartbeat() {
        if (emitters.isEmpty()) return;

        log.debug("Sending SSE heartbeats for {} sessions", emitters.size());
        emitters.forEach((sessionId, list) -> {
            for (SseEmitter emitter : list) {
                try {
                    emitter.send(SseEmitter.event()
                            .name("ping")
                            .comment("keep-alive"));
                } catch (IOException | IllegalStateException e) {
                    log.debug("Removing broken emitter for session {}: {}", sessionId, e.getMessage());
                    removeEmitter(sessionId, emitter);
                }
            }
        });
    }

    /**
     * Gọi sau mỗi lần SV quét QR thành công (từ ClassSessionService).
     * Đẩy bản ghi điểm danh đã cập nhật tới tất cả GV đang subscribe.
     */
    public void pushAttendanceUpdate(Long sessionId, Attendance attendance) {
        CopyOnWriteArrayList<SseEmitter> sessionEmitters = emitters.get(sessionId);
        if (sessionEmitters == null || sessionEmitters.isEmpty()) return;

        AttendanceSummaryDto dto = toDto(attendance);

        for (SseEmitter emitter : sessionEmitters) {
            try {
                emitter.send(SseEmitter.event()
                        .name("attendance-update")  // client lắng nghe event tên này
                        .data(dto));
            } catch (IOException | IllegalStateException e) {
                log.warn("Failed to push update to emitter, removing. sessionId={}", sessionId);
                removeEmitter(sessionId, emitter);
            }
        }
    }

    /**
     * Gọi khi GV đóng buổi học — báo client kết thúc stream.
     */
    public void pushSessionClosed(Long sessionId) {
        CopyOnWriteArrayList<SseEmitter> sessionEmitters = emitters.get(sessionId);
        if (sessionEmitters == null) return;

        for (SseEmitter emitter : sessionEmitters) {
            try {
                emitter.send(SseEmitter.event()
                        .name("session-closed")
                        .data("Buổi học đã kết thúc"));
                emitter.complete();
            } catch (IOException | IllegalStateException e) {
                log.warn("Failed to send session-closed event. sessionId={}", sessionId);
                removeEmitter(sessionId, emitter);
            }
        }
        emitters.remove(sessionId);
    }

    // ----------------------------------------------------------------
    // Helper
    // ----------------------------------------------------------------

    private List<AttendanceSummaryDto> buildSnapshot(Long sessionId) {
        return attendanceRepository.findAttendanceSummaryBySessionId(sessionId);
    }

    private AttendanceSummaryDto toDto(Attendance a) {
        return new AttendanceSummaryDto(
                a.getId(),
                a.getStudent().getStudentCode(),
                a.getStudent().getUser().getFullName(),
                a.getStatus(),
                a.getScannedAt(),
                a.getIsLate(),
                a.getLateMinutes() != null ? (short) a.getLateMinutes() : null,
                a.getCheckedOutAt(),
                a.getLeftEarly(),
                a.getGpsVerified()
        );
    }

    private void removeEmitter(Long sessionId, SseEmitter emitter) {
        CopyOnWriteArrayList<SseEmitter> list = emitters.get(sessionId);
        if (list != null) {
            list.remove(emitter);
            if (list.isEmpty()) emitters.remove(sessionId);
        }
    }

    /**
     * Gọi từ CheckoutEventScheduler sau khi markLeftEarlyForSession().
     * Nhiều SV bị cập nhật cùng lúc nên gửi lại toàn bộ snapshot thay vì từng record.
     */
    public void pushLeftEarlyUpdate(Long sessionId) {
        CopyOnWriteArrayList<SseEmitter> sessionEmitters = emitters.get(sessionId);
        if (sessionEmitters == null || sessionEmitters.isEmpty()) return;

        List<AttendanceSummaryDto> snapshot = buildSnapshot(sessionId);

        for (SseEmitter emitter : sessionEmitters) {
            try {
                emitter.send(SseEmitter.event()
                        .name("left-early-update")   // client phân biệt với "attendance-update"
                        .data(snapshot));
            } catch (IOException | IllegalStateException e) {
                log.warn("Failed to push left-early-update. sessionId={}", sessionId);
