    }

    /**
     * Lấy danh sách sinh viên của 1 buổi học để điểm danh/chỉnh sửa thủ công
     * Hỗ trợ filter theo status, search theo mã SV hoặc tên
     */
    public List<StudentAttendanceItemDto> getStudentAttendanceListForManualEdit(
            Long sessionId, String searchBy, String status, Integer page, Integer pageSize) {

        // Validate: GV chỉ được xem buổi học của mình
        ClassSession session = getAndValidateLecturerSession(sessionId, false);

        // Kiểm tra buổi học phải ở trạng thái open hoặc closed
        if (session.getStatus() == ClassSession.Status.scheduled || session.getStatus() == ClassSession.Status.cancelled) {
            throw new AppException(ErrorCode.INVALID_SESSION_STATUS);
        }

        // Lấy danh sách điểm danh từ DB
        List<Attendance> attendances = attendanceRepository.findByClassSession_Id(sessionId);

        // Filter theo status nếu có
        if (status != null && !status.trim().isEmpty()) {
            try {
                Attendance.Status filterStatus = Attendance.Status.valueOf(status.toLowerCase());
                attendances = attendances.stream()
                        .filter(a -> a.getStatus() == filterStatus)
                        .toList();
            } catch (IllegalArgumentException e) {
                throw new AppException(ErrorCode.INVALID_ATTENDANCE_STATUS);
            }
        }

        // Filter theo searchBy (mã SV hoặc tên) nếu có
        if (searchBy != null && !searchBy.trim().isEmpty()) {
            String searchLower = searchBy.toLowerCase().trim();
            attendances = attendances.stream()
                    .filter(a -> a.getStudent().getUser().getFullName().toLowerCase().contains(searchLower) ||
                           a.getStudent().getStudentCode().toLowerCase().contains(searchLower))
                    .toList();
        }

        // Convert sang DTO
        List<StudentAttendanceItemDto> result = attendances.stream()
                .map(this::toStudentAttendanceItemDto)
                .toList();

        // Pagination (simple client-side pagination)
        int startIdx = page * pageSize;
        int endIdx = Math.min(startIdx + pageSize, result.size());

        return result.subList(startIdx, endIdx);
    }

    /**
     * Cập nhật điểm danh thủ công
     * Ghi lại lịch sử chỉnh sửa
     */
    @Transactional
    public ManualAttendanceUpdateResponse updateAttendanceManually(
            Long sessionId, Long attendanceId, ManualAttendanceUpdateRequest request) {

        // Validate session & permission
        ClassSession session = getAndValidateLecturerSession(sessionId, true);

        // Lấy bản ghi điểm danh
        Attendance attendance = attendanceRepository.findById(attendanceId)
                .orElseThrow(() -> new AppException(ErrorCode.ATTENDANCE_NOT_FOUND));

        // Validate: attendance phải của buổi học này
        if (!attendance.getClassSession().getId().equals(sessionId)) {
            throw new AppException(ErrorCode.NO_PERMISSION_ON_SESSION);
        }

        // Cập nhật trạng thái
        Attendance.Status oldStatus = attendance.getStatus();
        attendance.setStatus(request.getNewStatus());

        // Nếu đổi thành present, cập nhật là lẽ (late info)
        if (request.getNewStatus() == Attendance.Status.present) {
            attendance.setIsLate(request.getIsLate());
            if (request.getIsLate()) {
                attendance.setLateMinutes(request.getLateMinutes());
            } else {
                attendance.setLateMinutes((short) 0);
            }
        } else {
            // Nếu không present, xóa thông tin lẽ
            attendance.setIsLate(false);
            attendance.setLateMinutes(null);
        }

        // Ghi lại lịch sử chỉnh sửa
        Long currentLecturerId = securityUtils.getCurrentLecturerId();
        Lecturer lecturer = new Lecturer();
        lecturer.setId(currentLecturerId);

        User editor = new User();
        editor.setId(securityUtils.getCurrentUserId());

        attendance.setEditedBy(editor);
        attendance.setEditedAt(LocalDateTime.now());
        attendance.setNote(request.getReason());

        // Lưu vào DB
        Attendance updated = attendanceRepository.save(attendance);

        // Convert sang DTO để trả về
        StudentAttendanceItemDto updatedDto = toStudentAttendanceItemDto(updated);

        String message = String.format("Cập nhật thành công: %s từ '%s' thành '%s'", 
            updated.getStudent().getStudentCode(), oldStatus, request.getNewStatus());

        return ManualAttendanceUpdateResponse.builder()
                .success(true)
                .message(message)
                .updatedRecord(updatedDto)
                .build();
    }

    /**
     * Convert Attendance entity sang StudentAttendanceItemDto
     */
    private StudentAttendanceItemDto toStudentAttendanceItemDto(Attendance attendance) {
        return StudentAttendanceItemDto.builder()
                .studentId(attendance.getStudent().getId())
                .attendanceId(attendance.getId())
                .studentCode(attendance.getStudent().getStudentCode())
                .fullName(attendance.getStudent().getUser().getFullName())
                .currentStatus(attendance.getStatus())
                .isLate(attendance.getIsLate())
                .lateMinutes(attendance.getLateMinutes())
                .scannedAt(attendance.getScannedAt())
                .checkedOutAt(attendance.getCheckedOutAt())
                .gpsVerified(attendance.getGpsVerified())
                .distanceM(attendance.getDistanceM())
                .lastEditedAt(attendance.getEditedAt())
                .lastEditedByName(attendance.getEditedBy() != null ? attendance.getEditedBy().getFullName() : null)
                .lastEditNote(attendance.getNote())
                .needsReview(determineNeedsReview(attendance))
                .reviewReason(getReviewReason(attendance))
                .build();
    }

    /**
     * Xác định record có cần review hay không
     */
    private Boolean determineNeedsReview(Attendance attendance) {
        // Cần review nếu: bị edit tay, GPS failed, device overlap, ...
        if (attendance.getEditedAt() != null) {
            return true;
        }
        if (attendance.getGpsVerified() == Boolean.FALSE && attendance.getClassSession().getGpsEnabled()) {
            return true;
        }
        return false;
    }

    /**
     * Lý do cần review
     */
    private String getReviewReason(Attendance attendance) {
        if (attendance.getEditedAt() != null) {
            return "Đã được chỉnh sửa thủ công";
        }
        if (attendance.getGpsVerified() == Boolean.FALSE && attendance.getClassSession().getGpsEnabled()) {
            return "GPS verification failed";
        }
        return null;
    }
}

