package ken.example.dekiru.common.Exception;

import lombok.Getter;
import org.springframework.http.HttpStatus;

@Getter // Dùng Lombok để tự động tạo Getter cho code, message, httpStatus
public enum ErrorCode {
    UNCATEGORIZED_EXCEPTION(9999, "Uncategorized exception", HttpStatus.INTERNAL_SERVER_ERROR),
    ROLE_EXISTED(1000, "Role existed", HttpStatus.BAD_REQUEST),
    USERNAME_INVALID(1001, "User name must be at least 3 characters", HttpStatus.BAD_REQUEST),
    EMAIL_EXISTED(1002, "Email existed", HttpStatus.BAD_REQUEST),
    EMAIL_NOT_EXISTED(1003, "Email not existed", HttpStatus.NOT_FOUND),
    UNAUTHENTICATION(1004, "Unauthenticated", HttpStatus.UNAUTHORIZED),
    INVALID_REFRESH_TOKEN(1005, "Invalid refresh token", HttpStatus.UNAUTHORIZED), // Sửa lỗi chính tả tên biến
    ROLE_NOT_EXISTED(1111, "Role not existed", HttpStatus.NOT_FOUND),
    FACULTY_NOT_EXISTED(1112, "Faculty not existed", HttpStatus.NOT_FOUND),
    SUBJECT_NOT_EXISTED(1113, "Subject not existed", HttpStatus.NOT_FOUND),
    ROOM_NOT_EXISTED(1114, "Room not existed", HttpStatus.NOT_FOUND),
    SEMESTER_NOT_EXISTED(1115, "Semester not existed", HttpStatus.NOT_FOUND),
    DEPARTMENT_NOT_EXISTED(1116, "Department not existed", HttpStatus.NOT_FOUND),
    ADMINISTRATIVE_CLASS_NOT_EXISTED(1117, "Administrative class not existed", HttpStatus.NOT_FOUND),
    INVALID_START_DATE(1118, "Start date must be Monday", HttpStatus.BAD_REQUEST),
    INVALID_DATE_RANGE(1119, "End date must be after start date", HttpStatus.BAD_REQUEST),
    FILE_IS_EMPTY(1006, "File tải lên đang trống", HttpStatus.BAD_REQUEST),
    FILE_PROCESSING_ERROR(1007, "Lỗi khi đọc hoặc xử lý file Excel", HttpStatus.INTERNAL_SERVER_ERROR),
    INVALID_FILE_FORMAT(1008, "Định dạng file không hợp lệ, vui lòng dùng file .xlsx", HttpStatus.BAD_REQUEST);

    private final int code;
    private final String message;
    private final HttpStatus httpStatus; // Thêm trường này

    ErrorCode(int code, String message, HttpStatus httpStatus) {
        this.code = code;
        this.message = message;
        this.httpStatus = httpStatus;
    }
}

