package ken.example.dekiru.Service;

import ken.example.dekiru.DTO.Response.ImportResponse;
import ken.example.dekiru.DTO.Response.FacultyResponse;
import ken.example.dekiru.Entity.Faculty;
import ken.example.dekiru.Mapper.FacultyMapper;
import ken.example.dekiru.Repository.FacultyRepository;
import ken.example.dekiru.Repository.DepartmentRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Workbook;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class FacultyService {

    FacultyRepository facultyRepository;
    DepartmentRepository departmentRepository;
    FacultyMapper facultyMapper;

    @Transactional
    public ImportResponse importExcel(MultipartFile file) {
        if (file.isEmpty()) {
            throw new AppException(ErrorCode.FILE_IS_EMPTY);
        }

        int successCount = 0;
        int updateCount = 0;
        int errorCount = 0;
        List<String> errorDetails = new ArrayList<>();
        List<Faculty> facultiesToSave = new ArrayList<>();
        Set<String> codesInCurrentFile = new HashSet<>();
        int totalRows = 0;

        // PHASE 1: Đọc file Excel (catch lỗi file)
        try (InputStream inputStream = file.getInputStream();
             Workbook workbook = new XSSFWorkbook(inputStream)) {

            Sheet sheet = workbook.getSheetAt(0);
            totalRows = sheet.getLastRowNum();

            // ✅ Validate headers
            Row headerRow = sheet.getRow(0);
            if (headerRow == null) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }
            List<String> expectedHeaders = List.of("Mã khoa", "Tên khoa");
            if (!validateHeaders(headerRow, expectedHeaders)) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }

            //  FIX N+1: Batch load
            List<String> codesInFile = new ArrayList<>();
            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;
                String code = getCellValue(row.getCell(0));
                if (!code.isEmpty()) {
                    codesInFile.add(code);
                }
            }

            Map<String, Faculty> existingFacultiesMap = new HashMap<>();
            if (!codesInFile.isEmpty()) {
                List<Faculty> existingFaculties = facultyRepository.findAllByCodeIn(codesInFile);
                for (Faculty faculty : existingFaculties) {
                    existingFacultiesMap.put(faculty.getCode(), faculty);
                }
            }

            // Process từng dòng
            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;

                try {
                    String code = getCellValue(row.getCell(0));
                    String name = getCellValue(row.getCell(1));

                    if (code.isEmpty() && name.isEmpty()) {
                        continue;
                    }

                    if (code.isEmpty() || name.isEmpty()) {
                        throw new RuntimeException("Mã khoa hoặc Tên khoa không được để trống");
                    }

                    //  FIX DUPLICATE
                    if (codesInCurrentFile.contains(code)) {
                        throw new RuntimeException("Mã khoa '" + code + "' bị trùng trong file Excel");
                    }
                    codesInCurrentFile.add(code);

                    Faculty existingFaculty = existingFacultiesMap.get(code);

                    if (existingFaculty != null) {
                        if (!existingFaculty.getName().equals(name)) {
                            existingFaculty.setName(name);
                            facultiesToSave.add(existingFaculty);
                            updateCount++;
                        }
                    } else {
                        Faculty newFaculty = Faculty.builder()
                                .code(code)
                                .name(name)
                                .build();
                        facultiesToSave.add(newFaculty);
                        successCount++;
                    }
                } catch (Exception e) {
                    errorCount++;
                    errorDetails.add("Dòng " + (i + 1) + ": " + e.getMessage());
                }
            }

        } catch (Exception e) {
            // ❌ Chỉ catch lỗi file Excel (IOException, XSSFException, ...)
            throw new AppException(ErrorCode.FILE_PROCESSING_ERROR);
        }

        // PHASE 2: Lưu Database (NGOÀI khối try-catch của file)
        // ✅ Nếu lỗi DB, sẽ throw ra đúng, không bị mask
        if (!facultiesToSave.isEmpty()) {
            facultyRepository.saveAll(facultiesToSave);
        }

        return ImportResponse.builder()
                .totalRows(totalRows)
                .successCount(successCount)
                .updateCount(updateCount)
                .errorCount(errorCount)
                .errors(errorDetails)
                .build();
    }

    // ✅ Helper: Validate headers
    private boolean validateHeaders(Row headerRow, List<String> expectedHeaders) {
        for (int i = 0; i < expectedHeaders.size(); i++) {
            Cell cell = headerRow.getCell(i);
            String headerValue = getCellValue(cell).trim();
            if (!headerValue.equals(expectedHeaders.get(i))) {
                return false;
            }
        }
        return true;
    }

    // Hàm tiện ích: Lấy dữ liệu ô an toàn
    // Tự động ép kiểu (để nếu user nhập mã khoa là số 123, app cũng không báo lỗi)
    private String getCellValue(Cell cell) {
        if (cell == null) return "";
        cell.setCellType(CellType.STRING);
        return cell.getStringCellValue().trim();
    }

    // Lấy danh sách tất cả các khoa
    public List<FacultyResponse> getAllFaculties() {
        List<Faculty> faculties = facultyRepository.findAll();
        return facultyMapper.toFacultyResponseList(faculties);
    }

    // Lấy thông tin khoa theo ID
    public FacultyResponse getFacultyById(Long id) {
        Faculty faculty = facultyRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.FACULTY_NOT_EXISTED));
        return facultyMapper.toFacultyResponse(faculty);
    }

    // ✅ Xóa khoa
    public void deleteFaculty(Long id) {
        Faculty faculty = facultyRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.FACULTY_NOT_EXISTED));

        // Check: Khoa có bộ môn không?
        long departmentCount = departmentRepository.countByFacultyId(id);
        if (departmentCount > 0) {
            throw new AppException(ErrorCode.FACULTY_HAS_DEPARTMENTS);
        }

        facultyRepository.deleteById(id);
    }

package ken.example.dekiru.Service;

import ken.example.dekiru.DTO.Response.ImportResponse;
import ken.example.dekiru.DTO.Response.FacultyResponse;
import ken.example.dekiru.Entity.Faculty;
import ken.example.dekiru.Mapper.FacultyMapper;
import ken.example.dekiru.Repository.FacultyRepository;
import ken.example.dekiru.Repository.DepartmentRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Workbook;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class FacultyService {

    FacultyRepository facultyRepository;
    DepartmentRepository departmentRepository;
    FacultyMapper facultyMapper;

    @Transactional
    public ImportResponse importExcel(MultipartFile file) {
        if (file.isEmpty()) {
            throw new AppException(ErrorCode.FILE_IS_EMPTY);
        }

        int successCount = 0;
        int updateCount = 0;
        int errorCount = 0;
        List<String> errorDetails = new ArrayList<>();
        List<Faculty> facultiesToSave = new ArrayList<>();
        Set<String> codesInCurrentFile = new HashSet<>();
        int totalRows = 0;

        // PHASE 1: Đọc file Excel (catch lỗi file)
        try (InputStream inputStream = file.getInputStream();
             Workbook workbook = new XSSFWorkbook(inputStream)) {

            Sheet sheet = workbook.getSheetAt(0);
            totalRows = sheet.getLastRowNum();

            // ✅ Validate headers
            Row headerRow = sheet.getRow(0);
            if (headerRow == null) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }
            List<String> expectedHeaders = List.of("Mã khoa", "Tên khoa");
            if (!validateHeaders(headerRow, expectedHeaders)) {
                throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
            }

            //  FIX N+1: Batch load
            List<String> codesInFile = new ArrayList<>();
            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;
                String code = getCellValue(row.getCell(0));
                if (!code.isEmpty()) {
                    codesInFile.add(code);
                }
            }

            Map<String, Faculty> existingFacultiesMap = new HashMap<>();
            if (!codesInFile.isEmpty()) {
                List<Faculty> existingFaculties = facultyRepository.findAllByCodeIn(codesInFile);
                for (Faculty faculty : existingFaculties) {
                    existingFacultiesMap.put(faculty.getCode(), faculty);
                }
            }

            // Process từng dòng
            for (int i = 1; i <= totalRows; i++) {
                Row row = sheet.getRow(i);
                if (row == null) continue;

                try {
                    String code = getCellValue(row.getCell(0));
                    String name = getCellValue(row.getCell(1));

                    if (code.isEmpty() && name.isEmpty()) {
                        continue;
                    }

                    if (code.isEmpty() || name.isEmpty()) {
                        throw new RuntimeException("Mã khoa hoặc Tên khoa không được để trống");
                    }

                    //  FIX DUPLICATE
                    if (codesInCurrentFile.contains(code)) {
                        throw new RuntimeException("Mã khoa '" + code + "' bị trùng trong file Excel");
                    }
                    codesInCurrentFile.add(code);

                    Faculty existingFaculty = existingFacultiesMap.get(code);

                    if (existingFaculty != null) {
                        if (!existingFaculty.getName().equals(name)) {
                            existingFaculty.setName(name);
                            facultiesToSave.add(existingFaculty);
                            updateCount++;
                        }
                    } else {
                        Faculty newFaculty = Faculty.builder()
                                .code(code)
                                .name(name)
                                .build();
                        facultiesToSave.add(newFaculty);
                        successCount++;
                    }
                } catch (Exception e) {
                    errorCount++;
                    errorDetails.add("Dòng " + (i + 1) + ": " + e.getMessage());
                }
            }

        } catch (Exception e) {
            // ❌ Chỉ catch lỗi file Excel (IOException, XSSFException, ...)
            throw new AppException(ErrorCode.FILE_PROCESSING_ERROR);
        }

        // PHASE 2: Lưu Database (NGOÀI khối try-catch của file)
        // ✅ Nếu lỗi DB, sẽ throw ra đúng, không bị mask
        if (!facultiesToSave.isEmpty()) {
            facultyRepository.saveAll(facultiesToSave);
        }

        return ImportResponse.builder()
                .totalRows(totalRows)
                .successCount(successCount)
                .updateCount(updateCount)
                .errorCount(errorCount)
                .errors(errorDetails)
                .build();
    }

    // ✅ Helper: Validate headers
    private boolean validateHeaders(Row headerRow, List<String> expectedHeaders) {
        for (int i = 0; i < expectedHeaders.size(); i++) {
            Cell cell = headerRow.getCell(i);
            String headerValue = getCellValue(cell).trim();
            if (!headerValue.equals(expectedHeaders.get(i))) {
                return false;
            }
        }
        return true;
    }

    // Hàm tiện ích: Lấy dữ liệu ô an toàn
    // Tự động ép kiểu (để nếu user nhập mã khoa là số 123, app cũng không báo lỗi)
    private String getCellValue(Cell cell) {
        if (cell == null) return "";
        cell.setCellType(CellType.STRING);
        return cell.getStringCellValue().trim();
    }

    // Lấy danh sách tất cả các khoa
    public List<FacultyResponse> getAllFaculties() {
        List<Faculty> faculties = facultyRepository.findAll();
        return facultyMapper.toFacultyResponseList(faculties);
    }

    // Lấy thông tin khoa theo ID
    public FacultyResponse getFacultyById(Long id) {
        Faculty faculty = facultyRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.FACULTY_NOT_EXISTED));
        return facultyMapper.toFacultyResponse(faculty);
    }

    // ✅ Xóa khoa
    public void deleteFaculty(Long id) {
        Faculty faculty = facultyRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.FACULTY_NOT_EXISTED));

        // Check: Khoa có bộ môn không?
        long departmentCount = departmentRepository.countByFacultyId(id);
        if (departmentCount > 0) {
            throw new AppException(ErrorCode.FACULTY_HAS_DEPARTMENTS);
        }

        facultyRepository.deleteById(id);
    }
}

package ken.example.dekiru.common.Exception;

import ken.example.dekiru.common.ApiReponse.ApiResponse;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.context.request.async.AsyncRequestTimeoutException;

@RestControllerAdvice
public class GlobalExceptionHandler {
    // Bắt lỗi do chúng ta chủ động ném ra
    @ExceptionHandler(AppException.class)
    public ResponseEntity<ApiResponse<?>> handlingAppException(AppException appException, WebRequest request){
        ErrorCode errorCode = appException.getErrorCode();

        ApiResponse<?> apiResponse = ApiResponse.builder()
                .code(errorCode.getCode())
                .message(errorCode.getMessage())
                .build();

        // Trả về HTTP Status động dựa theo cấu hình trong Enum
        // Force Content-Type là application/json cho các kết nối SSE bị lỗi lúc Subscribe
        return ResponseEntity
                .status(errorCode.getHttpStatus())
                .contentType(isSseRequest(request) ? MediaType.TEXT_PLAIN : MediaType.APPLICATION_JSON)
                .body(apiResponse);
    }

    // Bắt tất cả các lỗi RuntimeException khác chưa được lường trước
    @ExceptionHandler(Exception.class)
    public ResponseEntity<?> handlingRuntimeException(Exception exception, WebRequest request){
        // Kiểm tra nếu là lỗi ngắt kết nối Client của SSE
        if (exception.getMessage() != null && exception.getMessage().contains("disconnected client")) {
            return null; // Trả về null để Spring kết thúc request mà không cố gắng ghi đè dữ liệu
        }

        ApiResponse<?> apiResponse = ApiResponse.builder()
                .code(ErrorCode.UNCATEGORIZED_EXCEPTION.getCode())
                .message(ErrorCode.UNCATEGORIZED_EXCEPTION.getMessage())
                .build();

        return ResponseEntity
                .status(ErrorCode.UNCATEGORIZED_EXCEPTION.getHttpStatus())
                .contentType(isSseRequest(request) ? MediaType.TEXT_PLAIN : MediaType.APPLICATION_JSON)
                .body(apiResponse);
    }

    private boolean isSseRequest(WebRequest request) {
        String acceptHeader = request.getHeader("Accept");
        return acceptHeader != null && acceptHeader.contains(MediaType.TEXT_EVENT_STREAM_VALUE);
    }

    @ExceptionHandler(AsyncRequestTimeoutException.class)
    public void handleAsyncRequestTimeoutException() {
        // Để trống thế này.
        // Trình duyệt sẽ tự động kết nối lại (reconnect) một ống nước mới 30 phút nữa.
    }
}

package ken.example.dekiru.common.Exception;

import ken.example.dekiru.common.ApiReponse.ApiResponse;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.context.request.async.AsyncRequestTimeoutException;

@RestControllerAdvice
public class GlobalExceptionHandler {
    // Bắt lỗi do chúng ta chủ động ném ra
    @ExceptionHandler(AppException.class)
    public ResponseEntity<ApiResponse<?>> handlingAppException(AppException appException, WebRequest request){
        ErrorCode errorCode = appException.getErrorCode();

        ApiResponse<?> apiResponse = ApiResponse.builder()
                .code(errorCode.getCode())
                .message(errorCode.getMessage())
                .build();

        // Trả về HTTP Status động dựa theo cấu hình trong Enum
        // Force Content-Type là application/json cho các kết nối SSE bị lỗi lúc Subscribe
        return ResponseEntity
                .status(errorCode.getHttpStatus())
                .contentType(isSseRequest(request) ? MediaType.TEXT_PLAIN : MediaType.APPLICATION_JSON)
                .body(apiResponse);
    }

    // Bắt tất cả các lỗi RuntimeException khác chưa được lường trước
    @ExceptionHandler(Exception.class)
    public ResponseEntity<?> handlingRuntimeException(Exception exception, WebRequest request){
        // Kiểm tra nếu là lỗi ngắt kết nối Client của SSE (chặn cả tin nhắn và loại trừ loại exception cụ thể của Tomcat/Spring)
        String message = exception.getMessage();
        if (message != null && (message.contains("disconnected client") || message.contains("Broken pipe") || message.contains("Connection reset by peer"))) {
            return null; 
        }

        // Nếu là HttpMessageNotWritableException phát sinh sau khi đã ngắt kết nối
        if (exception instanceof org.springframework.http.converter.HttpMessageNotWritableException && isSseRequest(request)) {
            return null;
        }

        ApiResponse<?> apiResponse = ApiResponse.builder()
                .code(ErrorCode.UNCATEGORIZED_EXCEPTION.getCode())
                .message(ErrorCode.UNCATEGORIZED_EXCEPTION.getMessage())
                .build();

        return ResponseEntity
                .status(ErrorCode.UNCATEGORIZED_EXCEPTION.getHttpStatus())
                .contentType(isSseRequest(request) ? MediaType.TEXT_PLAIN : MediaType.APPLICATION_JSON)
                .body(apiResponse);
    }

    private boolean isSseRequest(WebRequest request) {
        String acceptHeader = request.getHeader("Accept");
        return acceptHeader != null && acceptHeader.contains(MediaType.TEXT_EVENT_STREAM_VALUE);
    }

    @ExceptionHandler(AsyncRequestTimeoutException.class)
    public void handleAsyncRequestTimeoutException() {
        // Để trống thế này.
        // Trình duyệt sẽ tự động kết nối lại (reconnect) một ống nước mới 30 phút nữa.
    }
}

package ken.example.dekiru.Controller;

