package ken.example.dekiru.Controller;

import ken.example.dekiru.DTO.Response.ImportResponse;
import ken.example.dekiru.DTO.Response.RoomResponse;
import ken.example.dekiru.Service.RoomService;
import ken.example.dekiru.common.ApiReponse.ApiResponse;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.util.List;

@RestController
@RequestMapping("/admin/rooms")
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class RoomController {

    RoomService roomService;

    @GetMapping
    public ApiResponse<List<RoomResponse>> getAllRooms() {
        List<RoomResponse> rooms = roomService.getAllRooms();
        return ApiResponse.success(rooms, "Lấy danh sách phòng thành công");
    }

    @GetMapping("/{id}")
    public ApiResponse<RoomResponse> getRoomById(@PathVariable Long id) {
        RoomResponse room = roomService.getRoomById(id);
        return ApiResponse.success(room, "Lấy thông tin phòng thành công");
    }

    @PostMapping("/import")
    public ApiResponse<ImportResponse> importRooms(@RequestParam("file") MultipartFile file) {
        String contentType = file.getContentType();
        if (contentType == null || !contentType.equals("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")) {
            throw new AppException(ErrorCode.INVALID_FILE_FORMAT);
        }
        ImportResponse report = roomService.importExcel(file);
        return ApiResponse.success(report, "Đã xử lý xong file dữ liệu.");
    }
}

package ken.example.dekiru.Service;

import ken.example.dekiru.DTO.Request.CreateSemesterRequest;
import ken.example.dekiru.DTO.Request.UpdateSemesterRequest;
import ken.example.dekiru.DTO.Response.SemesterResponse;
import ken.example.dekiru.Entity.Semester;
import ken.example.dekiru.Mapper.SemesterMapper;
import ken.example.dekiru.Repository.SemesterRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DayOfWeek;
import java.util.List;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class SemesterService {

    SemesterRepository semesterRepository;
    SemesterMapper semesterMapper;

    // Lấy danh sách tất cả các học kỳ
    public List<SemesterResponse> getAllSemesters() {
        List<Semester> semesters = semesterRepository.findAll();
        return semesterMapper.toSemesterResponseList(semesters);
    }

    // Lấy thông tin học kỳ theo ID
    public SemesterResponse getSemesterById(Long id) {
        Semester semester = semesterRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.SEMESTER_NOT_EXISTED));
        return semesterMapper.toSemesterResponse(semester);
    }

    // Tạo học kỳ mới
    @Transactional
    public SemesterResponse createSemester(CreateSemesterRequest request) {
        // Validate startDate phải là Thứ Hai
        DayOfWeek dayOfWeek = request.getStartDate().getDayOfWeek();
        if (dayOfWeek != DayOfWeek.MONDAY) {
            throw new AppException(ErrorCode.INVALID_START_DATE);
        }

        // Validate endDate > startDate
        if (request.getEndDate().isBefore(request.getStartDate())) {
            throw new AppException(ErrorCode.INVALID_DATE_RANGE);
        }

        // Dùng Mapper để convert Request → Entity
        Semester semester = semesterMapper.toSemester(request);

        // Mặc định isActive = false khi create mới
        semester.setIsActive(false);

        Semester saved = semesterRepository.save(semester);
        return semesterMapper.toSemesterResponse(saved);
    }

    // ✅ Sửa học kỳ (sửa name, isActive với validation)
    @Transactional
    public SemesterResponse updateSemester(Long id, UpdateSemesterRequest request) {
        Semester semester = semesterRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.SEMESTER_NOT_EXISTED));

        if (request.getName() != null && !request.getName().trim().isEmpty()) {
            semester.setName(request.getName());
        }

        if (request.getIsActive() != null) {
            // Nếu set isActive = true → validate khoảng thời gian
            if (request.getIsActive()) {
                java.time.LocalDate today = java.time.LocalDate.now();
                // Kiểm tra: startDate ≤ today ≤ endDate
                if (today.isBefore(semester.getStartDate()) || today.isAfter(semester.getEndDate())) {
                    throw new AppException(ErrorCode.INVALID_DATE_RANGE);
                }

                // Tắt tất cả semester khác
                semesterRepository.findByIsActiveTrue().ifPresent(existing -> {
                    existing.setIsActive(false);
                    semesterRepository.save(existing);
                });
                semester.setIsActive(true);
            } else {
                // Nếu set isActive = false → validate có thể tắt không
                // TODO: Khi ScheduleRepository được implement, thêm check:
                // long scheduleCount = scheduleRepository.countBySemesterId(id);
                // if (scheduleCount > 0) {
                //     java.time.LocalDate today = java.time.LocalDate.now();
                //     // Chỉ tắt được nếu học kỳ đã kết thúc (endDate < today)
                //     if (today.isBefore(semester.getEndDate())) {
                //         throw new AppException(ErrorCode.CANNOT_DEACTIVATE_ONGOING_SEMESTER);
                //     }
                // }
                semester.setIsActive(false);
            }
        }

        Semester updated = semesterRepository.save(semester);
        return semesterMapper.toSemesterResponse(updated);
    }

    // ✅ Xóa học kỳ
    public void deleteSemester(Long id) {
        Semester semester = semesterRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.SEMESTER_NOT_EXISTED));

        // Note: Khi ScheduleRepository được implement, thêm check:
        // long scheduleCount = scheduleRepository.countBySemesterId(id);
        // if (scheduleCount > 0) {
        //     throw new AppException(ErrorCode.SEMESTER_HAS_SCHEDULES);
        // }

        semesterRepository.deleteById(id);
    }
}

package ken.example.dekiru.Service;

import ken.example.dekiru.DTO.Request.CreateSemesterRequest;
import ken.example.dekiru.DTO.Request.UpdateSemesterRequest;
import ken.example.dekiru.DTO.Response.SemesterResponse;
import ken.example.dekiru.Entity.Semester;
import ken.example.dekiru.Mapper.SemesterMapper;
import ken.example.dekiru.Repository.SemesterRepository;
import ken.example.dekiru.common.Exception.AppException;
import ken.example.dekiru.common.Exception.ErrorCode;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DayOfWeek;
import java.util.List;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class SemesterService {

    SemesterRepository semesterRepository;
    SemesterMapper semesterMapper;

    // Lấy danh sách tất cả các học kỳ
    public List<SemesterResponse> getAllSemesters() {
        List<Semester> semesters = semesterRepository.findAll();
        return semesterMapper.toSemesterResponseList(semesters);
    }

    // Lấy thông tin học kỳ theo ID
    public SemesterResponse getSemesterById(Long id) {
        Semester semester = semesterRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.SEMESTER_NOT_EXISTED));
        return semesterMapper.toSemesterResponse(semester);
    }

    // Tạo học kỳ mới
    @Transactional
    public SemesterResponse createSemester(CreateSemesterRequest request) {
        // Validate startDate phải là Thứ Hai
        DayOfWeek dayOfWeek = request.getStartDate().getDayOfWeek();
        if (dayOfWeek != DayOfWeek.MONDAY) {
            throw new AppException(ErrorCode.INVALID_START_DATE);
        }

        // Validate endDate > startDate
        if (request.getEndDate().isBefore(request.getStartDate())) {
            throw new AppException(ErrorCode.INVALID_DATE_RANGE);
        }

        // Dùng Mapper để convert Request → Entity
        Semester semester = semesterMapper.toSemester(request);

        // Mặc định isActive = false khi create mới
        semester.setIsActive(false);

        Semester saved = semesterRepository.save(semester);
        return semesterMapper.toSemesterResponse(saved);
    }

    // ✅ Sửa học kỳ (sửa name, isActive)
    @Transactional
    public SemesterResponse updateSemester(Long id, UpdateSemesterRequest request) {
        Semester semester = semesterRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.SEMESTER_NOT_EXISTED));

        if (request.getName() != null && !request.getName().trim().isEmpty()) {
            semester.setName(request.getName());
        }

        if (request.getIsActive() != null) {
            // Nếu set isActive = true → tắt tất cả semester khác (trừ chính nó)
            if (request.getIsActive()) {
                semesterRepository.findByIsActiveTrue().ifPresent(existing -> {
                    // Guard: Không tắt chính nó
                    if (!existing.getId().equals(id)) {
                        existing.setIsActive(false);
                        semesterRepository.save(existing);
                    }
                });
                semester.setIsActive(true);
            } else {
                // Nếu set isActive = false → tắt luôn
                // TODO: Khi ScheduleRepository được implement, thêm check:
                // long scheduleCount = scheduleRepository.countBySemesterId(id);
                // if (scheduleCount > 0) {
                //     java.time.LocalDate today = java.time.LocalDate.now();
                //     // Chỉ tắt được nếu học kỳ đã kết thúc (endDate < today)
                //     if (today.isBefore(semester.getEndDate())) {
                //         throw new AppException(ErrorCode.CANNOT_DEACTIVATE_ONGOING_SEMESTER);
                //     }
                // }
                semester.setIsActive(false);
            }
        }

        Semester updated = semesterRepository.save(semester);
        return semesterMapper.toSemesterResponse(updated);
    }

    // ✅ Xóa học kỳ
    public void deleteSemester(Long id) {
        Semester semester = semesterRepository.findById(id)
                .orElseThrow(() -> new AppException(ErrorCode.SEMESTER_NOT_EXISTED));

        // Note: Khi ScheduleRepository được implement, thêm check:
        // long scheduleCount = scheduleRepository.countBySemesterId(id);
        // if (scheduleCount > 0) {
        //     throw new AppException(ErrorCode.SEMESTER_HAS_SCHEDULES);
        // }

        semesterRepository.deleteById(id);
    }
}

