package ken.example.dekiru.Service;
import ken.example.dekiru.DTO.Request.StudentExcelDTO;
import ken.example.dekiru.DTO.Request.LecturerExcelDTO;
import ken.example.dekiru.DTO.Request.UpdateStudentRequest;
